import{d as g,C as a,o as d,c as h,a3 as o,E as r,j as n,a as p}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第九章","description":"《正易心法》第九章——乾坤错杂，乃生六子：一阴入乾之下中上生巽离兑，一阳入坤之下中上生震坎艮，六子皆乾坤破体，入位决定卦性。","frontmatter":{"title":"正易心法·第九章","description":"《正易心法》第九章——乾坤错杂，乃生六子：一阴入乾之下中上生巽离兑，一阳入坤之下中上生震坎艮，六子皆乾坤破体，入位决定卦性。","category":"guide","aliases":["正易心法第九章","乾坤错杂乃生六子","破体"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-09.md","filePath":"yijing/zheng-yi-xin-fa/chapter-09.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-09.md"},f=g({...c,setup(u){const e=[{id:"z9-01",label:"一、六子即破体",showLabel:!0,sentences:[["乾坤",{text:"错杂",glossary:"cuoza"},"，乃生",{text:"六子",glossary:"liuzi"},"。六子则是，乾坤",{text:"破体",glossary:"poti"},"。"]],note:["乾坤阴阳交错混杂，于是生出六个子卦；六子卦的生成，正是乾坤纯体被打破的结果。（这是第八章「三代祖孙之别」的第一次具体展开：乾坤是祖，六子是孙，「破体」是生成机制。它回答了一个根本问题——为什么是这八个卦，而不是别的？因为每个子卦由「乾坤哪个位置被打破」决定。）"]},{id:"z9-02",label:"二、乾破体生三女",showLabel:!0,sentences:[["乾三画奇，纯阳也。一阴杂于下，是为巽；杂于中，是为离；杂于上，是为兑。"]],note:["乾卦三爻皆奇（阳），是纯阳之体：一阴混入初爻，成为巽；混入中爻，成为离；混入上爻，成为兑。（入位决定卦性：阴入下则巽——柔顺潜伏在根基，故「入」；阴入中则离——阴藏阳中，故「丽」；阴入上则兑——柔在其上、开口于顶，故「说」。）"]},{id:"z9-03",label:"三、皆破乾之纯阳",showLabel:!0,sentences:[["巽、离、兑，皆破乾之纯阳也。"]],note:["巽、离、兑，都是乾的纯阳之体被打破的结果。（三女卦的「破」是同一件事的三个位置：一阴入乾，入得越上，阳气越往外走——下则潜伏、中则含藏、上则外浮。这与《说卦传》「巽一索而得女，故谓之长女」是同一结果、不同路径。）"]},{id:"z9-04",label:"四、坤破体生三男",showLabel:!0,sentences:[["坤三画偶，纯阴也。一阳杂于下，是为震；杂于中，是为坎；杂于上，是为艮。"]],note:["坤卦三爻皆偶（阴），是纯阴之体：一阳混入初爻，成为震；混入中爻，成为坎；混入上爻，成为艮。（入位决定卦性：阳入下则震——阳气从地下爆发，故「动」；阳入中则坎——阳被阴包围，故「陷」；阳入上则艮——阳气凝止于顶，故「止」。）"]},{id:"z9-05",label:"五、皆破坤之纯体",showLabel:!0,sentences:[["震、坎、艮，皆破坤之纯体也。"]],note:["震、坎、艮，都是坤的纯阴之体被打破的结果。（「破体」不是破坏，而是生育：乾坤相交如父母交合，一阴入乾是母气渗入父体，一阳入坤是父气渗入母体，六子由此诞生。这与《系辞传》「乾道成男，坤道成女」相吻合，但麻衣更进一步——具体说明哪个位置被破，生出哪个卦。）"]},{id:"z9-06",label:"六、以人身求之",showLabel:!0,sentences:[["若更以人身求之，理自",{text:"昭然",glossary:"zhaoran"},"。"]],note:["若再用人体来对应验证，道理自然昭然若揭。（《说卦传》的对应是：乾为首、坤为腹、震为足、巽为股、坎为耳、离为目、艮为手、兑为口。麻衣的意思：人体的结构，正是乾坤破体的自然写照——不需要文字解释，对照卦画与人体，「理自昭然」。）"]}],s=[{id:"cuoza",term:"错杂",pinyin:"cuò zá",meaning:"交错混杂。指乾坤的阴阳相互渗入。"},{id:"liuzi",term:"六子",pinyin:"liù zǐ",meaning:"六个子卦：震、巽、坎、离、艮、兑。由乾坤破体而生。"},{id:"poti",term:"破体",pinyin:"pò tǐ",meaning:"破坏纯粹的本体。纯阳／纯阴被一爻异类打破——不是破坏，而是生育。"},{id:"zhaoran",term:"昭然",pinyin:"zhāo rán",meaning:"明白显著，一目了然。"}];return(b,t)=>{const i=a("DaoTextReading"),l=a("DaoKeywordCards");return d(),h("div",null,[t[0]||(t[0]=o("",21)),r(i,{colophon:"乾坤错杂 · 乃生六子 · 破体生育 · 入位定性",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第九章原文",sections:e,glossary:s}),t[1]||(t[1]=n("blockquote",null,[n("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),t[2]||(t[2]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[p("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),r(l,{items:[{term:"破体",pinyin:["pò","tǐ"],meaning:"纯阳／纯阴被一爻异类打破。不是破坏，而是生育——乾坤相交而六子诞生的机制。"},{term:"一阴杂于下中上",pinyin:["yī","yīn"],meaning:"阴入乾之初爻为巽、入中爻为离、入上爻为兑——三女卦的生成。"},{term:"一阳杂于下中上",pinyin:["yī","yáng"],meaning:"阳入坤之初爻为震、入中爻为坎、入上爻为艮——三男卦的生成。"},{term:"入位定性",pinyin:["rù","wèi"],meaning:"入下则动（震）／入（巽）；入中则陷（坎）／丽（离）；入上则止（艮）／说（兑）。位置决定卦性。"},{term:"以人身求之",pinyin:["rén","shēn"],meaning:"乾为首、坤为腹、震为足、巽为股、坎为耳、离为目、艮为手、兑为口——人体结构正是破体的写照。"}]}),t[3]||(t[3]=o("",24))])}}});export{y as __pageData,f as default};
